async function formBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk.toString();
    if (Buffer.byteLength(body) > 1024 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (req.method === 'GET' && url.pathname === '/') {
      projectList(res, '', url.searchParams.get('filter') === 'Archived' ? 'Archived' : 'Active');
      return;
    }
    if (req.method === 'POST' && url.pathname === '/projects') {
      const body = await formBody(req);
      const name = (body.get('name') || '').trim();
      if (!name) {
        projectList(res, 'Project name is required');
        return;
      }
      db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      res.writeHead(303, { Location: '/' });
      res.end();
      return;
    }
    const renameMatch = /^\/projects\/(\d+)\/rename$/.exec(url.pathname);
    if (req.method === 'POST' && renameMatch) {
      const project = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(renameMatch[1]);
      if (project) {
        if (project.archived) {
          sendHtml(res, 403, page('Archived project', '<h1>Archived project</h1><p>Archived projects cannot be changed.</p>'));
          return;
        }
        const body = await formBody(req);
        const filter = taskFilter(body.get('filter'));
        const priority = priorityFilter(body.get('priorityFilter'));
        const name = (body.get('name') || '').trim();
        if (!name) {
          projectPage(res, project, filter, 'Project name is required', priority);
          return;
        }
        db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, project.id);
        res.writeHead(303, { Location: projectLocation(project.id, filter, priority) });
        res.end();
        return;
      }
    }
    const archiveMatch = /^\/projects\/(\d+)\/(archive|restore)$/.exec(url.pathname);
    if (req.method === 'POST' && archiveMatch) {
      const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?')
        .run(archiveMatch[2] === 'archive' ? 1 : 0, archiveMatch[1]);
      if (result.changes) {
        res.writeHead(303, { Location: archiveMatch[2] === 'archive' ? '/' : '/?filter=Archived' });
        res.end();
        return;
      }
    }
    const taskMatch = /^\/projects\/(\d+)\/tasks(?:\/(\d+)(\/(?:rename|priority))?)?$/.exec(url.pathname);
    if (req.method === 'POST' && taskMatch) {
      const project = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(taskMatch[1]);
      if (project) {
        if (project.archived) {
          sendHtml(res, 403, page('Archived project', '<h1>Archived project</h1><p>Archived projects cannot be changed.</p>'));
          return;
        }
        const body = await formBody(req);
        const filter = taskFilter(body.get('filter'));
        const selectedPriority = priorityFilter(body.get('priorityFilter'));
        if (taskMatch[3] === '/priority') {
          const priority = body.get('priority');
          if (!['Low', 'Normal', 'High'].includes(priority)) {
            sendHtml(res, 400, page('Invalid priority', '<p role="alert">Invalid task priority</p>'));
            return;
          }
          const result = db.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?')
            .run(priority, taskMatch[2], project.id);
          if (!result.changes) {
            sendHtml(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        } else if (taskMatch[3] === '/rename') {
          const task = db.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?').get(taskMatch[2], project.id);
          if (!task) {
            sendHtml(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
          const title = (body.get('title') || '').trim();
          if (!title) {
            projectPage(res, project, filter, 'Task title is required', selectedPriority);
            return;
          }
          db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?').run(title, task.id, project.id);
        } else if (taskMatch[2]) {
          const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?')
            .run(body.get('completed') === '1' ? 1 : 0, taskMatch[2], project.id);
          if (!result.changes) {
            sendHtml(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        } else {
          const title = (body.get('title') || '').trim();
          if (!title) {
            projectPage(res, project, filter, 'Task title is required', selectedPriority);
            return;
          }
          db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(project.id, title);
        }
        res.writeHead(303, { Location: projectLocation(project.id, filter, selectedPriority) });
        res.end();
        return;
      }
    }
    const match = /^\/projects\/(\d+)$/.exec(url.pathname);
    if (req.method === 'GET' && match) {
      const project = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(match[1]);
      if (project) {
        projectPage(res, project, taskFilter(url.searchParams.get('filter')), '', priorityFilter(url.searchParams.get('priorityFilter')));
        return;
      }
    }
    sendHtml(res, 404, page('Not found', '<h1>Not found</h1><form action="/" method="get"><button>Projects</button></form>'));
  } catch (error) {
    if (error.status === 413) {
      res.writeHead(413);
      res.end('Request too large');
      return;
    }
    console.error(error);
    if (!res.headersSent) res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Internal server error');
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
